function winnerSquareGame(n) {
  // Forward marking: from every losing pile, adding a square gives a pile the mover wins.
  const winning = new Array(n + 1).fill(false);
  for (let pile = 0; pile <= n; pile++) {
    if (winning[pile]) continue;
    for (let root = 1; pile + root * root <= n; root++) winning[pile + root * root] = true;
  }
  return winning[n];
}

