function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size !== 'large') return [int(1, 60)];
  let n = int(50000, 100000);
  if (rand() < 0.5) {
    // Half of the large cases move down to the nearest pile Alice loses, so both answers appear.
    const wins = new Array(n + 1).fill(false);
    for (let s = 1; s <= n; s++) for (let k = 1; k * k <= s; k++) if (!wins[s - k * k]) { wins[s] = true; break; }
    while (n > 1 && wins[n]) n--;
    if (n < 1) n = 2;
  }
  return [n];
}
